from taf.fdsw.rc.clients.http.http_client import RCHttpClient
from taf.fdsw.rc.interfaces.fdsw import FDSW
from taf.fdsw.rc.interfaces.FDSW18SP.autoconnection import AutoConfiguration
from taf.fdsw.rc.interfaces.FDSW18SP.diagnostics import Diagnostics
from taf.fdsw.rc.interfaces.FDSW18SP.security import Security18SP
from taf.fdsw.rc.interfaces.FDSW18SP.swm import SoftwareManagement


class FDSW18SP(FDSW):
    API_VERSION = "1.0"
    API_SCHEMA_VERSION = "2.0"
    VERSION_NAME = 'FDSW18SP'
    _client = None

    def __init__(self, ip_address, port, username, password, secure=True):
        self._client = RCHttpClient(
            ip_address=ip_address,
            port=port,
            username=username,
            password=password,
            secure=secure,
            api_version=self.API_VERSION,
            api_schema_version=self.API_SCHEMA_VERSION
        )

        self._client.connect()

        self.swm = SoftwareManagement(client=self._client)

        self.security = Security18SP(client=self._client)

        self.autoconnection = AutoConfiguration(client=self._client)

        self.diagnostics = Diagnostics(client=self._client)

    def disconnect(self):
        self.swm.clear_sw_update_cache()
        super(FDSW18SP, self).disconnect()
